{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "DiPOA, a spiperone-like analogue bearing a carboxylic acid and a basic piperidine to form a zwitterion, has a brain-to-plasma ratio of only 0.019 in rats and lacks CNS efficacy, directly demonstrating that adding an ionizable acid to this scaffold severely limits meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A zwitterionic spiperone-type analogue showed very low brain/blood ratios (0.04-0.10) in rats, attributed to poor BBB diffusion, supporting that zwitterionic analogues of this scaffold have inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The closely related spiperone PET tracer 18F-FESP, which lacks the carboxylic acid, easily crosses the BBB, showing that the core scaffold is permeable when not rendered zwitterionic by an acidic group.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query is a zwitterionic spiperone-like carboxylic acid with low passive permeability and likely efflux liability. Direct evidence from DiPOA and another zwitterionic analogue shows very low CNS exposure for this scaffold when an acidic group is present, despite the permeable parent scaffold.",
  "evidence_gaps": [
    "No direct brain, plasma, CSF, or PK measurement exists for the exact query molecule.",
    "DiPOA differs in side chain (diphenylpropyl vs butyrophenone) and acid attachment position, so transfer is not exact.",
    "Efflux transporter liability is inferred but not experimentally confirmed for the query.",
    "Computed logD and ionization state may have some uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

